import java.util.HashMap;
import java.util.Map;
import org.apache.lucene.analysis.standard.StandardAnalyzer;
import org.apache.lucene.queryparser.classic.MultiFieldQueryParser;
import org.apache.lucene.search.Query;

public class Repro {
  public static void main(String[] args) throws Exception {
    String[] fields = new String[] {"field1"};
    Map<String, Float> boosts = new HashMap<>();
    boosts.put("field1", 1.5f);
    try (StandardAnalyzer analyzer = new StandardAnalyzer()) {
      MultiFieldQueryParser p1 = new MultiFieldQueryParser(fields, analyzer, boosts);
      Query q1 = p1.parse("\"hello world\"~1");
      System.out.println("with boost:    " + q1);

      MultiFieldQueryParser p2 = new MultiFieldQueryParser(fields, analyzer);
      Query q2 = p2.parse("\"hello world\"~1");
      System.out.println("without boost: " + q2);

      if (q1.toString().equals("field1:\"hello world\"~1^1.5")) {
        System.out.println("FIXED");
      } else {
        System.out.println("STILL BROKEN");
        System.exit(1);
      }
    }
  }
}

